SUBSECTION.TEXT:
Щоб проілюструвати одну з труднішостей, які можуть виникнути, припустімо, що ми хочемо банківський рахунокобмін балансами обміняти баланси двох банківських рахунків. Ми звертаємося до кожного рахунку, щоб знайти баланс, обчислюємо різницю між балансами, знімаємо цю різницю з одного рахунку і вносимо її на інший рахунок. Ми могли б реалізувати це так:Ми спростили exchange, скориставшись тим, що наше повідомлення deposit приймає від’ємні суми. (Це серйозна вада нашої банківської системи!)
exchange_example
a1 = make_account(100) a2 = make_account(200) a3 = make_account(300)
def peter(): print(a1("balance"), "Peter balance a1 before") print(a2("balance"), "Peter balance a2 before") exchange(a1, a2) print(a1("balance"), "Peter balance a1 after") print(a2("balance"), "Peter balance a2 after")
def paul(): print(a1("balance"), "Paul balance a1 before") print(a3("balance"), "Paul balance a3 before") exchange(a1, a3) print(a1("balance"), "Paul balance a1 after") print(a3("balance"), "Paul balance a3 after")
print(concurrent_execute(peter, paul))
exchange exchange make_account_serialize_attempt exchange_example
(define (exchange account1 account2) (let ((difference (- (account1 'balance) (account2 'balance)))) ((account1 'withdraw) difference) ((account2 'deposit) difference)))
def exchange(account1, account2): difference = account1("balance") - account2("balance") account1("withdraw")(difference) account2("deposit")(difference)

Експортування серіалізатора в такий спосіб дає нам достатньо гнучкості, щоб реалізувати серіалізовану програму обміну. Ми просто серіалізуємо початкову exchange процедуру функцію серіалізаторами обох рахунків:
serialized_exchange_example
a1 = make_account_and_serializer(100) a2 = make_account_and_serializer(200) a3 = make_account_and_serializer(300)
def peter(): print(a1("balance"), "Peter balance a1 before") print(a2("balance"), "Peter balance a2 before") serialized_exchange(a1, a2) print(a1("balance"), "Peter balance a1 after") print(a2("balance"), "Peter balance a2 after")
def paul(): print(a1("balance"), "Paul balance a1 before") print(a3("balance"), "Paul balance a3 before") serialized_exchange(a1, a3) print(a1("balance"), "Paul balance a1 after") print(a3("balance"), "Paul balance a3 after")
print(concurrent_execute(peter, paul))
serialized_exchange serialized_exchange make_account_and_serializer exchange serialized_exchange_example
(define (serialized-exchange account1 account2) (let ((serializer1 (account1 'serializer)) (serializer2 (account2 'serializer))) ((serializer1 (serializer2 exchange)) account1 account2)))
def serialized_exchange(account1, account2): serializer1 = account1("serializer") serializer2 = account2("serializer") serializer1(serializer2(exchange))(account1, account2)
